import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"name":"All-Barun Social Enterprise System","colors":{"surface":"#f7f9fb","surface-dim":"#d8dadc","surface-bright":"#f7f9fb","surface-container-lowest":"#ffffff","surface-container-low":"#f2f4f6","surface-container":"#eceef0","surface-container-high":"#e6e8ea","surface-container-highest":"#e0e3e5","on-surface":"#191c1e","on-surface-variant":"#43474a","inverse-surface":"#2d3133","inverse-on-surface":"#eff1f3","outline":"#73787b","outline-variant":"#c3c7ca","surface-tint":"#506169","primary":"#000508","on-primary":"#ffffff","primary-container":"#0f2027","on-primary-container":"#778891","inverse-primary":"#b7c9d3","secondary":"#006a62","on-secondary":"#ffffff","secondary-container":"#83f2e5","on-secondary-container":"#006f67","tertiary":"#000404","on-tertiary":"#ffffff","tertiary-container":"#002220","on-tertiary-container":"#009590","error":"#ba1a1a","on-error":"#ffffff","error-container":"#ffdad6","on-error-container":"#93000a","primary-fixed":"#d3e5ef","primary-fixed-dim":"#b7c9d3","on-primary-fixed":"#0d1e25","on-primary-fixed-variant":"#384951","secondary-fixed":"#86f5e8","secondary-fixed-dim":"#68d8cc","on-secondary-fixed":"#00201d","on-secondary-fixed-variant":"#00504a","tertiary-fixed":"#84f5ee","tertiary-fixed-dim":"#66d8d2","on-tertiary-fixed":"#00201e","on-tertiary-fixed-variant":"#00504d","background":"#f7f9fb","on-background":"#191c1e","surface-variant":"#e0e3e5"},"typography":{"display":{"fontFamily":"notoSans","fontSize":"48px","fontWeight":"700","lineHeight":"1.2"},"h1":{"fontFamily":"notoSans","fontSize":"36px","fontWeight":"700","lineHeight":"1.3"},"h2":{"fontFamily":"notoSans","fontSize":"28px","fontWeight":"700","lineHeight":"1.4"},"body-lg":{"fontFamily":"notoSans","fontSize":"20px","fontWeight":"400","lineHeight":"1.6"},"body-base":{"fontFamily":"notoSans","fontSize":"18px","fontWeight":"400","lineHeight":"1.6"},"ui-button":{"fontFamily":"notoSans","fontSize":"16px","fontWeight":"500","lineHeight":"1.0"},"label-sm":{"fontFamily":"notoSans","fontSize":"14px","fontWeight":"500","lineHeight":"1.4"},"display-mobile":{"fontFamily":"notoSans","fontSize":"32px","fontWeight":"700","lineHeight":"1.2"},"h1-mobile":{"fontFamily":"notoSans","fontSize":"28px","fontWeight":"700","lineHeight":"1.3"}},"rounded":{"sm":"0.25rem","DEFAULT":"0.5rem","md":"0.75rem","lg":"1rem","xl":"1.5rem","full":"9999px"},"spacing":{"base":"8px","gutter":"24px","margin-mobile":"16px","margin-desktop":"48px","stack-sm":"12px","stack-md":"24px","stack-lg":"40px"}},"headers":[],"relativePath":"design-landingpage.md","filePath":"design-landingpage.md"}'),r={name:"design-landingpage.md"};function n(s,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h2 id="brand-style" tabindex="-1">Brand &amp; Style <a class="header-anchor" href="#brand-style" aria-label="Permalink to &quot;Brand &amp; Style&quot;">​</a></h2><p>The design system is anchored in the concept of &quot;Righteous Stewardship.&quot; As a B2B social enterprise specializing in facility management, the visual language must balance high-tier professional authority with a palpable commitment to sustainability and social good.</p><p>The style is <strong>Corporate / Modern</strong> with a focus on high-readability and premium execution. It utilizes expansive whitespace to reflect the hygiene and order inherent in facility management, while employing a sophisticated &quot;Clean Green&quot; accent to signify vitality and environmental responsibility. The emotional response should be one of absolute reliability, transparency, and modern efficiency.</p><h2 id="colors" tabindex="-1">Colors <a class="header-anchor" href="#colors" aria-label="Permalink to &quot;Colors&quot;">​</a></h2><p>The palette is designed to project stability and cleanliness:</p><ul><li><strong>Primary (Deep Navy):</strong> Used for core branding, primary navigation, and heavy headings to establish authority and security.</li><li><strong>Secondary (Emerald Clean Green):</strong> Used for primary actions, success states, and indicators of sustainability or hygiene.</li><li><strong>Tertiary (Teal):</strong> A supportive hue for data visualization and secondary interactive elements.</li><li><strong>Background (Crisp Gray/White):</strong> The interface relies on #F8FAFC for sectional backing and pure #FFFFFF for cards and content containers to maintain a sterile, professional environment.</li></ul><h2 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h2><p>This design system prioritizes accessibility through a &quot;Large-Scale&quot; typographic approach, increasing standard sizes by roughly 15% to ensure ease of use for facility managers and diverse stakeholders.</p><p>We use <strong>Noto Sans KR</strong> exclusively to provide a clean, humanist feel that supports both Korean and Latin characters with equal poise. Headings are strictly Bold (700) to provide a firm structure, while body text uses Regular (400) with generous line heights (1.6) to reduce visual fatigue during data-heavy management tasks.</p><h2 id="layout-spacing" tabindex="-1">Layout &amp; Spacing <a class="header-anchor" href="#layout-spacing" aria-label="Permalink to &quot;Layout &amp; Spacing&quot;">​</a></h2><p>The layout follows a <strong>Fixed Grid</strong> philosophy for dashboard views to maintain a sense of structured control, transitioning to a fluid model for content-heavy pages.</p><ul><li><strong>Desktop:</strong> 12-column grid with 24px gutters. Content is centered with a max-width of 1280px.</li><li><strong>Tablet:</strong> 8-column grid with 20px gutters.</li><li><strong>Mobile:</strong> 4-column grid with 16px margins.</li></ul><p>Spacing follows an 8px geometric scale. Vertical rhythm is critical; use <code>stack-lg</code> (40px) between major sections to preserve the &quot;premium whitespace&quot; narrative.</p><h2 id="elevation-depth" tabindex="-1">Elevation &amp; Depth <a class="header-anchor" href="#elevation-depth" aria-label="Permalink to &quot;Elevation &amp; Depth&quot;">​</a></h2><p>Depth is achieved through <strong>Tonal Layers</strong> supplemented by <strong>Ambient Shadows</strong>. This design system avoids heavy shadows in favor of subtle, diffused lifts that make elements appear integrated rather than floating.</p><ul><li><strong>Level 0 (Base):</strong> #F8FAFC background.</li><li><strong>Level 1 (Cards):</strong> Pure white background with a 1px border (#E2E8F0) or a very soft shadow (0px 4px 12px rgba(15, 32, 39, 0.05)).</li><li><strong>Level 2 (Popovers/Modals):</strong> High-diffusion shadow (0px 12px 32px rgba(15, 32, 39, 0.12)) to provide clear focal separation.</li></ul><p>Interactive elements use a slight vertical lift on hover to provide tactile feedback without breaking the minimalist aesthetic.</p><h2 id="shapes" tabindex="-1">Shapes <a class="header-anchor" href="#shapes" aria-label="Permalink to &quot;Shapes&quot;">​</a></h2><p>The shape language is defined as <strong>Rounded (Level 2)</strong>. Standard components utilize a 0.5rem (8px) radius. Larger containers, such as main content cards or hero sections, utilize <code>rounded-lg</code> (16px) to soften the professional tone and make the enterprise software feel more approachable and modern.</p><p>Buttons and input fields must maintain consistent 8px corners to ensure a &quot;tool-like&quot; precision. Pill shapes (3) are reserved exclusively for status chips (e.g., &quot;Completed&quot;, &quot;Active&quot;).</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="buttons" tabindex="-1">Buttons <a class="header-anchor" href="#buttons" aria-label="Permalink to &quot;Buttons&quot;">​</a></h3><ul><li><strong>Primary:</strong> Deep Navy background with white text. High-contrast, authoritative.</li><li><strong>Success/Action:</strong> Emerald Green background. Used for &quot;Submit,&quot; &quot;Approve,&quot; or &quot;Start Task.&quot;</li><li><strong>Ghost:</strong> Transparent background with 1px Navy or Green border. Used for secondary actions.</li></ul><h3 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h3><ul><li><strong>Style:</strong> 1px solid border (#CBD5E1) with 8px corner radius.</li><li><strong>Focus State:</strong> 2px solid Emerald Green border with a soft green outer glow.</li><li><strong>Labels:</strong> Always positioned above the field in <code>label-sm</code> Bold Navy.</li></ul><h3 id="chips-tags" tabindex="-1">Chips &amp; Tags <a class="header-anchor" href="#chips-tags" aria-label="Permalink to &quot;Chips &amp; Tags&quot;">​</a></h3><ul><li><strong>Status Tags:</strong> Pill-shaped with low-opacity background tints of the status color (e.g., Light Green background for &quot;Cleaned&quot; with Dark Green text).</li></ul><h3 id="cards" tabindex="-1">Cards <a class="header-anchor" href="#cards" aria-label="Permalink to &quot;Cards&quot;">​</a></h3><ul><li><strong>Container:</strong> White background, 16px corner radius, subtle Level 1 shadow.</li><li><strong>Header:</strong> 1px light gray bottom border to separate card titles from content.</li></ul><h3 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;Lists&quot;">​</a></h3><ul><li><strong>Service Items:</strong> High-row height (min 64px) with subtle hover states (#F1F5F9). Use Emerald Green icons for checklist items to reinforce the &quot;clean&quot; brand promise.</li></ul>',31)])])}const f=a(r,[["render",n]]);export{u as __pageData,f as default};
